import{_ as a,a as t}from"./chunks/lifecycle-diagram.DqhRXCS3.js";import{_ as o,o as r,c as i,a0 as n}from"./chunks/framework.tsJrOMu2.js";const f=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/README.md","filePath":"architecture/README.md"}'),l={name:"architecture/README.md"};function s(c,e,d,p,h,g){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Agentrail is organized as a layered framework. Understanding the layers is the fastest path to knowing where your code belongs and how to extend the framework without fighting it.</p><h2 id="the-stack" tabindex="-1">The Stack <a class="header-anchor" href="#the-stack" aria-label="Permalink to &quot;The Stack&quot;">​</a></h2><p><img src="'+a+'" alt="Agentrail architecture: three layers from top — Your App (dashed), @agentrail/app with @agentrail/capabilities, and @agentrail/core at the foundation."></p><p>Two design axes govern the stack:</p><p><strong>Vertical (dependency direction)</strong> — each layer depends on the one below it, never the reverse: <code>core ← capabilities ← app</code>. Your app depends on the framework; the framework does not depend on your app.</p><p><strong>Horizontal (composition)</strong> — <code>@agentrail/app</code> is wide, not just tall. It composes <code>@agentrail/capabilities</code> (sandbox, knowledge, skills, orchestration, tools) and <code>@agentrail/core</code> (runtime, prompts, session types) into a hosted request lifecycle.</p><h2 id="layer-map" tabindex="-1">Layer Map <a class="header-anchor" href="#layer-map" aria-label="Permalink to &quot;Layer Map&quot;">​</a></h2><h3 id="_1-agentrail-core" tabindex="-1">1. <code>@agentrail/core</code> <a class="header-anchor" href="#_1-agentrail-core" aria-label="Permalink to &quot;1. `@agentrail/core`&quot;">​</a></h3><p>The execution foundation. Defines agents, tool contracts (<code>defineTool</code>), the LLM provider abstraction, the agent loop, message types, prompt SDK, session type contracts, and usage tracking.</p><p>Everything else in the framework builds on this layer. It has no knowledge of HTTP, sessions, or host lifecycles.</p><h3 id="_2-agentrail-capabilities" tabindex="-1">2. <code>@agentrail/capabilities</code> <a class="header-anchor" href="#_2-agentrail-capabilities" aria-label="Permalink to &quot;2. `@agentrail/capabilities`&quot;">​</a></h3><p>Domain-specific building blocks that extend the agent&#39;s surface area. Provides:</p><ul><li>Filesystem and browser tools (sandboxed execution via Docker)</li><li>Knowledge-base indexing and retrieval</li><li>Skill discovery and execution</li><li>Multi-agent orchestration (sub-agents, mailboxing, waits, recovery)</li><li>General-purpose tools (web search, ask-user, todo writing, etc.)</li></ul><p>Capabilities are independently usable and injected through profiles via <code>defineProfile({ capabilities: [...] })</code>.</p><h3 id="_3-agentrail-app" tabindex="-1">3. <code>@agentrail/app</code> <a class="header-anchor" href="#_3-agentrail-app" aria-label="Permalink to &quot;3. `@agentrail/app`&quot;">​</a></h3><p>The main server-side integration package. Handles:</p><ul><li>HTTP request lifecycle via <code>createAgentApp</code> (chat and stream endpoints)</li><li>Profile definition via <code>defineProfile</code></li><li>Session management (<code>SessionManager</code>)</li><li>Plugin and slash-command extension model</li><li>Typed config loading</li><li>SSE event contracts</li></ul><p>Start here: <code>createAgentApp</code> is the recommended entry point for hosted deployments.</p><h3 id="_4-your-app" tabindex="-1">4. Your app <a class="header-anchor" href="#_4-your-app" aria-label="Permalink to &quot;4. Your app&quot;">​</a></h3><p>Profiles, routes, UI, and business logic. This is the code you write. It uses <code>@agentrail/app</code> and <code>@agentrail/core</code> but is not part of the framework itself.</p><h2 id="package-reference" tabindex="-1">Package Reference <a class="header-anchor" href="#package-reference" aria-label="Permalink to &quot;Package Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Layer</th><th>Purpose</th></tr></thead><tbody><tr><td><code>@agentrail/core</code></td><td>1</td><td>Agent loop, tool contracts, LLM providers, prompts, session types</td></tr><tr><td><code>@agentrail/capabilities</code></td><td>2</td><td>Sandbox, knowledge, skills, orchestration, built-in tools</td></tr><tr><td><code>@agentrail/app</code></td><td>3</td><td><code>createAgentApp</code>, <code>defineProfile</code>, sessions, plugins, config</td></tr><tr><td><code>@agentrail/cli</code></td><td>tooling</td><td>Local developer CLI (<code>agentrail doctor</code>, config checks, helpers)</td></tr><tr><td><code>@agentrail/testing</code></td><td>tooling</td><td>Test helpers for hosted apps and runtime behavior</td></tr><tr><td><code>@agentrail/deep-research</code></td><td>addon</td><td>Multi-agent deep research workflow</td></tr><tr><td><code>@agentrail/create-agentrail-app</code></td><td>tooling</td><td>Project scaffold CLI</td></tr></tbody></table><h2 id="request-lifecycle" tabindex="-1">Request Lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request Lifecycle&quot;">​</a></h2><p>Here is what happens when a message arrives at a stream endpoint:</p><p><img src="'+t+'" alt="Agentrail request lifecycle: 8-step flow from POST /api/stream through session, profile, history, compaction, context assembly, agent.stream SSE, persistence, and done."></p><p>The <code>/chat</code> endpoint follows the same steps but buffers the full response instead of streaming.</p><h2 id="recommended-vs-escape-hatch-apis" tabindex="-1">Recommended vs Escape-Hatch APIs <a class="header-anchor" href="#recommended-vs-escape-hatch-apis" aria-label="Permalink to &quot;Recommended vs Escape-Hatch APIs&quot;">​</a></h2><p>One of the core design ideas in Agentrail is a deliberate split between a recommended high-level path and lower-level escape hatches.</p><p>The primary entry points are:</p><ul><li><code>createAgentApp({ dataDir, profiles, ... })</code> — the recommended way to mount both <code>/chat</code> and <code>/stream</code> endpoints in one call</li><li><code>defineProfile(definition)</code> — declare profiles with agent config, capabilities, and optional per-request factory</li></ul><p>Lower-level escape hatches from <code>@agentrail/app/advanced</code> (use when you need finer control):</p><ul><li><code>createChatRoute(...)</code> — mount only the <code>/chat</code> primitive</li><li><code>createStreamRoute(...)</code> — mount only the <code>/stream</code> primitive</li><li><code>createOrchestrationRegistry(...)</code> — per-session orchestration manager</li></ul><p>Compatibility helpers still exist in <code>@agentrail/app/compat</code>, but they are migration-only APIs. Keep them out of new application code and refer to <a href="./../reference/host-defaults">Compatibility APIs</a> only when updating older hosts.</p><p>Start with <code>createAgentApp</code> + <code>defineProfile</code>. They are not black boxes — they are a recommended assembly of primitives that you can unwrap and replace piece by piece as your app grows.</p><p>The same principle applies throughout the framework: <code>@agentrail/core</code> provides execution primitives; <code>@agentrail/capabilities</code> provides reusable building blocks; <code>@agentrail/app</code> wires them into a recommended hosted path.</p><h2 id="recommended-development-path" tabindex="-1">Recommended Development Path <a class="header-anchor" href="#recommended-development-path" aria-label="Permalink to &quot;Recommended Development Path&quot;">​</a></h2><p>Approach the framework in this order to keep complexity proportional to need:</p><ol><li><strong>Read the quickstart</strong> — get a working app from the scaffold first</li><li><strong>Understand profiles and <code>@agentrail/app</code></strong> — this is where most application logic lives</li><li><strong>Use <code>createAgentApp</code> + <code>defineProfile</code></strong> — start here before reaching for lower-level primitives</li><li><strong>Add prompts and context providers early</strong> — they pay off quickly as apps grow</li><li><strong>Add capabilities and plugins where app-specific behavior appears</strong></li><li><strong>Add orchestration only when the problem actually needs multi-agent work</strong></li></ol><h2 id="framework-core-vs-application-code" tabindex="-1">Framework Core vs Application Code <a class="header-anchor" href="#framework-core-vs-application-code" aria-label="Permalink to &quot;Framework Core vs Application Code&quot;">​</a></h2><p>A useful boundary for contributors:</p><p><strong>Framework core</strong> (belongs in framework packages):</p><ul><li><code>@agentrail/core</code>, <code>@agentrail/capabilities</code>, <code>@agentrail/app</code></li></ul><p><strong>Application code</strong> (belongs in your app or example projects):</p><ul><li>concrete prompt content, concrete profile definitions, app-local plugins, route composition, UI-specific event rendering, workflow business logic</li></ul><p>Keeping this boundary clean is what makes Agentrail reusable as a framework rather than collapsing into a monolithic app.</p><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><ul><li>Stable primitives with a recommended SDK path on top.</li><li>Dependency direction is always framework → core, never the reverse.</li><li>Chat and stream routes share the same lifecycle concepts.</li><li>Capability packages are independently usable and optionally composed.</li><li>Business-domain logic stays out of framework core packages.</li></ul><h2 id="repository-reading-order" tabindex="-1">Repository Reading Order <a class="header-anchor" href="#repository-reading-order" aria-label="Permalink to &quot;Repository Reading Order&quot;">​</a></h2><ol><li><a href="./../concepts/agents">Concepts: Agents</a></li><li><a href="./../concepts/profiles">Concepts: Profiles</a></li><li><a href="./../guides/quickstart">Guides: Quickstart</a></li><li><a href="./../reference/profile-contract">Reference: Profile Contract</a></li><li><a href="./../reference/host-primitives">Reference: Host Primitives</a></li><li><a href="./../examples/playground-server">Examples: Playground Server</a></li></ol>',50)])])}const b=o(l,[["render",s]]);export{f as __pageData,b as default};
